insert into public.alerts (id, reference, segment_id, department_slug, title, detail, severity, status, occurred_at, source) values ('alt-01', 'ALR-2026-0418', 'seg-gm04', 'signalling', 'Sustained high vibration at Germiston West', 'REGEN-EDGE-GM03 recorded 14.8 mm/s peak across the last four passages — 2.3× the review threshold.', 'critical', 'open', '2026-11-10T05:44:00.000Z', 'REGEN-EDGE-GM03 · telemetry') on conflict (id) do nothing;
insert into public.alerts (id, reference, segment_id, department_slug, title, detail, severity, status, occurred_at, source) values ('alt-02', 'ALR-2026-0417', 'seg-kp01', 'substation', 'Substation earth fault reported', 'Kempton Park traction substation reported a transient earth fault on feeder B. Field verification pending.', 'high', 'open', '2026-11-10T05:00:00.000Z', 'Traction Power · SCADA') on conflict (id) do nothing;
insert into public.alerts (id, reference, segment_id, department_slug, title, detail, severity, status, occurred_at, source) values ('alt-03', 'ALR-2026-0416', 'seg-is02', 'ohte', 'Catenary dropper arcing', 'Driver report of arcing on the up line dropper at KM 9.4. OHTE patrol requested.', 'high', 'acknowledged', '2026-11-10T02:10:00.000Z', 'Train Crew · report') on conflict (id) do nothing;
insert into public.alerts (id, reference, segment_id, department_slug, title, detail, severity, status, occurred_at, source) values ('alt-04', 'ALR-2026-0415', 'seg-is02', 'permanent-way', 'Sensor gateway degradation', 'REGEN-EDGE-KP02 signal quality dropped to 61% and has missed two scheduled transmissions.', 'medium', 'acknowledged', '2026-11-10T01:20:00.000Z', 'REGEN gateway') on conflict (id) do nothing;
