insert into public.alerts (id, reference, segment_id, department_slug, title, detail, severity, status, occurred_at, source) values ('alt-06', 'ALR-2026-0413', 'seg-kw06', 'track-circuit', 'False occupation cleared', 'KW-06 track circuit false occupation investigated and cleared by the signalling team.', 'medium', 'resolved', '2026-11-09T16:40:00.000Z', 'Signalling · interlocking log') on conflict (id) do nothing;
insert into public.maintenance_reports (id, reference, title, description, segment_id, department_slug, severity, stage, reported_by, reported_at, photos, due_at, assigned_to, instructions, recommended_action, sensor_evidence, evidence_notes, completed_at, location_note) values ('rep-0142', 'MR-2026-0142', 'Traction substation earth fault — Kempton Park', 'Protection relay tripped on feeder B at Kempton Park traction substation. Insulation resistance on the outgoing feeder measured 2.1 MΩ against the 5 MΩ minimum. Field team reports scorching at the cable termination.', 'seg-kp01', 'substation', 'high', 'awaiting-authorisation', 'emp-0006', '2026-11-09T16:40:00.000Z', array['termination-scorch.jpg', 'relay-panel.jpg']::text[], '2026-11-11T07:20:00.000Z', null, null, 'Replace the feeder B cable termination and re-test insulation before re-energising.', 'REGEN-EDGE-KP01 shows an elevated vibration envelope consistent with a loaded feeder but no track-side anomaly. No structural strain channel available on this node.', null, null, 'Kempton Park traction substation · feeder B · bay 3') on conflict (id) do nothing;
insert into public.maintenance_reports (id, reference, title, description, segment_id, department_slug, severity, stage, reported_by, reported_at, photos, due_at, assigned_to, instructions, recommended_action, sensor_evidence, evidence_notes, completed_at, location_note) values ('rep-0141', 'MR-2026-0141', 'OHTE dropper arcing — Isando KM 9.4', 'Crew reported visible arcing at the fourth dropper east of Isando on the up line. Contact wire height measured 5.02 m against a 5.20 m nominal, indicating loss of tension.', 'seg-is02', 'ohte', 'high', 'assessed', 'emp-0009', '2026-11-09T09:20:00.000Z', array['dropper-arcing.jpg']::text[], '2026-11-10T19:20:00.000Z', null, null, 'Replace dropper assembly and re-tension the affected span during the next night possession.', 'REGEN-EDGE-KP02 recorded a 9.2 mm/s peak on the adjacent section. Footfall vibration is within the expected band for a loaded span.', null, null, 'Isando · KM 9.4 · up line · span 118') on conflict (id) do nothing;
insert into public.maintenance_reports (id, reference, title, description, segment_id, department_slug, severity, stage, reported_by, reported_at, photos, due_at, assigned_to, instructions, recommended_action, sensor_evidence, evidence_notes, completed_at, location_note) values ('rep-0139', 'MR-2026-0139', 'Track geometry deviation — Isando down line', 'Geometry car flagged a 12 mm cross-level deviation over a 20 m chord between KM 8.4 and KM 8.6. Tamping required before the deviation propagates.', 'seg-is02', 'permanent-way', 'medium', 'in-progress', 'emp-0003', '2026-11-07T11:00:00.000Z', array['geometry-trace.jpg', 'site-marking.jpg']::text[], '2026-11-12T07:20:00.000Z', 'emp-0004', 'Attend with the tamping team during the 22:00–04:00 possession. Confirm cross-level within 4 mm and record a post-work geometry run.', 'Tamp the affected 40 m and re-measure.', 'Vibration signature on KP-02 shows a repeatable impact at the same chainage on every down-line passage.', null, null, 'Isando · KM 8.4–8.6 · down line') on conflict (id) do nothing;
insert into public.maintenance_reports (id, reference, title, description, segment_id, department_slug, severity, stage, reported_by, reported_at, photos, due_at, assigned_to, instructions, recommended_action, sensor_evidence, evidence_notes, completed_at, location_note) values ('rep-0136', 'MR-2026-0136', 'Signalling cable theft — Germiston North', 'Approximately 40 m of signalling multicore cable removed between two location cases. Signals 14 and 16 are showing blank aspect. Protection arrangements requested.', 'seg-gm04', 'signalling', 'critical', 'verified', 'emp-0010', '2026-11-08T20:20:00.000Z', array['cable-trench.jpg']::text[], '2026-11-10T13:20:00.000Z', null, null, null, null, null, null, 'Germiston North · location case 14 to 16') on conflict (id) do nothing;
insert into public.maintenance_reports (id, reference, title, description, segment_id, department_slug, severity, stage, reported_by, reported_at, photos, due_at, assigned_to, instructions, recommended_action, sensor_evidence, evidence_notes, completed_at, location_note) values ('rep-0131', 'MR-2026-0131', 'Rail seat abrasion — Kempton Park down line', 'Visual inspection found rail seat abrasion on eleven consecutive sleepers at KM 0.4. Insulator pads degraded. Recommend pad replacement and fastener torque check.', 'seg-kp01', 'permanent-way', 'medium', 'completed', 'emp-0006', '2026-11-05T00:40:00.000Z', array['rail-seat.jpg', 'pad-wear.jpg']::text[], '2026-11-15T10:40:00.000Z', 'emp-0006', 'Replace insulator pads on the eleven affected sleepers, torque fastenings to 220 Nm and photograph each completed seat.', 'Replace pads and torque fastenings.', 'KP01 vibration amplitude reduced by 0.8 mm/s after pad replacement, consistent with improved rail seat condition.', 'Work completed during the 02:00 possession. Eleven pads replaced, fastenings torqued and logged. Photographs uploaded.', '2026-11-08T15:20:00.000Z', 'Kempton Park · KM 0.4 · down line') on conflict (id) do nothing;
insert into public.maintenance_reports (id, reference, title, description, segment_id, department_slug, severity, stage, reported_by, reported_at, photos, due_at, assigned_to, instructions, recommended_action, sensor_evidence, evidence_notes, completed_at, location_note) values ('rep-0128', 'MR-2026-0128', 'Track circuit false occupation — NS-05', 'Section showed occupied with no train in the block on three separate occasions between 06:10 and 07:05.', 'seg-ns05', 'track-circuit', 'medium', 'closed', 'emp-0002', '2026-11-03T12:00:00.000Z', '{}'::text[], '2026-11-16T23:20:00.000Z', 'emp-0010', 'Test impedance bond connections and adjust feed resistance. Record all readings.', 'Adjust feed resistance and re-test.', 'No sensor coverage on NS-05 at the time of the report.', 'Feed resistance adjusted from 4.8 Ω to 5.6 Ω. Three consecutive test trains detected correctly.', '2026-11-03T22:00:00.000Z', 'Natalspruit · NS-05 track circuit · feed end') on conflict (id) do nothing;
insert into public.maintenance_reports (id, reference, title, description, segment_id, department_slug, severity, stage, reported_by, reported_at, photos, due_at, assigned_to, instructions, recommended_action, sensor_evidence, evidence_notes, completed_at, location_note) values ('rep-0143', 'MR-2026-0143', 'Ballast shoulder erosion — Kaalfontein', 'Heavy rain has washed out the ballast shoulder over approximately 8 m on the up line. Sleeper ends are exposed and cribs are empty.', 'seg-kl10', 'permanent-way', 'high', 'reported', 'emp-0006', '2026-11-10T04:50:00.000Z', array['shoulder-erosion.jpg']::text[], null, null, null, null, null, null, null, 'Kaalfontein · KM 16.9 · up line') on conflict (id) do nothing;
insert into public.maintenance_reports (id, reference, title, description, segment_id, department_slug, severity, stage, reported_by, reported_at, photos, due_at, assigned_to, instructions, recommended_action, sensor_evidence, evidence_notes, completed_at, location_note) values ('rep-0144', 'MR-2026-0144', 'Signal lamp failure — Rissik home signal', 'Home signal R12 showing dark aspect. Lamp unit replacement required; no train delay reported at the time of logging.', 'seg-jb07', 'signalling', 'low', 'rejected', 'emp-0002', '2026-11-07T22:40:00.000Z', '{}'::text[], null, null, null, null, null, 'Duplicate of MR-2026-0129 — closed by the signalling manager.', null, 'Rissik · home signal R12') on conflict (id) do nothing;
